import{_ as e,o as a,c as l,a5 as n}from"./chunks/framework.DfywBLEo.js";const h=JSON.parse('{"title":"版本切换","description":"","frontmatter":{},"headers":[],"relativePath":"guide/versionSwitch.md","filePath":"guide/versionSwitch.md","lastUpdated":1792557099000}'),o={name:"guide/versionSwitch.md"};function p(t,s,r,i,c,d){return a(),l("div",null,[...s[0]||(s[0]=[n(`<h1 id="版本切换" tabindex="-1">版本切换 <a class="header-anchor" href="#版本切换" aria-label="Permalink to &quot;版本切换&quot;">​</a></h1><p>升级前先备份博客园后台的 CSS 和侧边栏公告。<strong>CSS 与 JavaScript 必须使用同一版本。</strong></p><h2 id="v2-内升级" tabindex="-1">v2 内升级 <a class="header-anchor" href="#v2-内升级" aria-label="Permalink to &quot;v2 内升级&quot;">​</a></h2><h3 id="使用-jsdelivr" tabindex="-1">使用 jsDelivr <a class="header-anchor" href="#使用-jsdelivr" aria-label="Permalink to &quot;使用 jsDelivr&quot;">​</a></h3><ol><li>从 <a href="https://github.com/BNDong/Cnblogs-Theme-SimpleMemory/releases" target="_blank" rel="noreferrer">Releases</a> 选择目标版本，阅读对应变更。</li><li>用目标版本的 <code>dist/simpleMemory.css</code> 完整替换后台的页面定制 CSS。</li><li>修改插件脚本地址中的版本号。保留自己的 <code>window.cnblogsConfig</code> 配置。</li></ol><p>例如，从 <code>v2.1.6</code> 升级到 <code>v2.1.7</code>：</p><div class="language-html line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki simplememory-plum vp-code" tabindex="0"><code><span class="line"><span style="color:#B8ABC9;">&lt;!-- 升级前 --&gt;</span></span>
<span class="line"><span style="color:#EEE6F7;">&lt;</span><span style="color:#F0ADC4;">script</span><span style="color:#F0ADC4;"> src</span><span style="color:#EEE6F7;">=</span><span style="color:#D1B4FA;">&quot;https://cdn.jsdelivr.net/gh/BNDong/Cnblogs-Theme-SimpleMemory@v2.1.6/dist/simpleMemory.js&quot;</span><span style="color:#F0ADC4;"> defer</span><span style="color:#EEE6F7;">&gt;&lt;/</span><span style="color:#F0ADC4;">script</span><span style="color:#EEE6F7;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><div class="language-html line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki simplememory-plum vp-code" tabindex="0"><code><span class="line"><span style="color:#B8ABC9;">&lt;!-- 升级后，同时替换 CSS --&gt;</span></span>
<span class="line"><span style="color:#EEE6F7;">&lt;</span><span style="color:#F0ADC4;">script</span><span style="color:#F0ADC4;"> src</span><span style="color:#EEE6F7;">=</span><span style="color:#D1B4FA;">&quot;https://cdn.jsdelivr.net/gh/BNDong/Cnblogs-Theme-SimpleMemory@v2.1.7/dist/simpleMemory.js&quot;</span><span style="color:#F0ADC4;"> defer</span><span style="color:#EEE6F7;">&gt;&lt;/</span><span style="color:#F0ADC4;">script</span><span style="color:#EEE6F7;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="使用自己的资源服务" tabindex="-1">使用自己的资源服务 <a class="header-anchor" href="#使用自己的资源服务" aria-label="Permalink to &quot;使用自己的资源服务&quot;">​</a></h3><p>上传目标版本的整个 <code>dist/</code> 目录，包含脚本、样式、图片和字体。不要只替换入口 JS，也不要混用不同构建生成的资源。</p><p>建议将各版本放入独立目录，再切换入口地址，例如：</p><div class="language-html line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki simplememory-plum vp-code" tabindex="0"><code><span class="line"><span style="color:#EEE6F7;">&lt;</span><span style="color:#F0ADC4;">script</span><span style="color:#F0ADC4;"> src</span><span style="color:#EEE6F7;">=</span><span style="color:#D1B4FA;">&quot;https://example.com/simplememory/v2.1.7/simpleMemory.js&quot;</span><span style="color:#F0ADC4;"> defer</span><span style="color:#EEE6F7;">&gt;&lt;/</span><span style="color:#F0ADC4;">script</span><span style="color:#EEE6F7;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>同一路径覆盖文件时，可以通过查询参数更新入口缓存：</p><div class="language-html line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki simplememory-plum vp-code" tabindex="0"><code><span class="line"><span style="color:#EEE6F7;">&lt;</span><span style="color:#F0ADC4;">script</span><span style="color:#F0ADC4;"> src</span><span style="color:#EEE6F7;">=</span><span style="color:#D1B4FA;">&quot;https://example.com/dist/simpleMemory.js?v=2.1.7&quot;</span><span style="color:#F0ADC4;"> defer</span><span style="color:#EEE6F7;">&gt;&lt;/</span><span style="color:#F0ADC4;">script</span><span style="color:#EEE6F7;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>查询参数只影响入口文件，不能代替上传其余资源。新版本确认正常前保留旧资源，避免已打开的页面继续请求旧文件时出现 404。资源目录要求见<a href="./resourceCdn.html">资源托管</a>。</p><h2 id="v1-与-v2-之间切换" tabindex="-1">v1 与 v2 之间切换 <a class="header-anchor" href="#v1-与-v2-之间切换" aria-label="Permalink to &quot;v1 与 v2 之间切换&quot;">​</a></h2><p>两个大版本的配置不兼容，需要按目标版本的文档重新配置。不要只修改脚本地址。</p><h2 id="升级后异常" tabindex="-1">升级后异常 <a class="header-anchor" href="#升级后异常" aria-label="Permalink to &quot;升级后异常&quot;">​</a></h2><p>先核对 CSS、JS 的版本和资源是否完整，再检查控制台与 Network 面板。需要回退时，同时恢复备份的 CSS、脚本地址和配置。</p>`,19)])])}const u=e(o,[["render",p]]);export{h as __pageData,u as default};
